using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.RegularExpressions;

namespace AppleCrash.Core;

public enum RoundPhase { Idle, Running, AwaitingRoll, CrashReview, RecoveryPaused, Completed }
public enum ParticipantStatus { InPlay, CashedOut, Lost, Refunded }
public sealed class PlayerAccount { public string Id { get; set; } = ""; public string Name { get; set; } = ""; public string World { get; set; } = ""; public long Balance { get; set; } public long PreferredBet { get; set; } public bool Enrolled { get; set; } public bool Archived { get; set; } }
public sealed class StepDefinition { public decimal From { get; set; } public decimal To { get; set; } public int? Threshold { get; set; } public int DelaySeconds { get; set; } public string Script { get; set; } = ""; }
public sealed class PluginSettings { public List<StepDefinition> Steps { get; set; } = []; public List<StepDefinition> ReferencePresets { get; set; } = []; public string RulesScript { get; set; } = ""; public string IntroScript { get; set; } = ""; public string WinTemplate { get; set; } = ""; public string LossTemplate { get; set; } = ""; public bool ChatSendingEnabled { get; set; } }
public sealed class RoundParticipant { public string PlayerId { get; set; } = ""; public string Name { get; set; } = ""; public string World { get; set; } = ""; public long Stake { get; set; } public ParticipantStatus Status { get; set; } public decimal? ExitMultiplier { get; set; } public long Payout { get; set; } }
public sealed class RoundState { public Guid Id { get; set; } public RoundPhase Phase { get; set; } public decimal Multiplier { get; set; } = 1m; public List<RoundParticipant> Participants { get; set; } = []; public StepDefinition? PendingStep { get; set; } public PluginSettings Snapshot { get; set; } = new(); public RoundPhase? ResumePhase { get; set; } }
public sealed class AuditEntry { public Guid TransactionId { get; set; } = Guid.NewGuid(); public DateTimeOffset Timestamp { get; set; } = DateTimeOffset.UtcNow; public string Kind { get; set; } = ""; public string PlayerId { get; set; } = ""; public string Reason { get; set; } = ""; public long Amount { get; set; } public Guid? RoundId { get; set; } public long? Before { get; set; } public long? After { get; set; } }
public sealed class LedgerState { public int SchemaVersion { get; set; } = 1; public string HostId { get; set; } = ""; public List<PlayerAccount> Players { get; set; } = []; public RoundState? Round { get; set; } public List<AuditEntry> Audit { get; set; } = []; public List<RoundState> History { get; set; } = []; }

public static class ChatParser {
    private static readonly Regex Stop = new(@"\bstop\b", RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
    private static readonly Regex Transition = new(@"(?<![\d.])(\d+(?:\.\d+)?)\s*(?:x)?\s*(?:to|[-→])\s*(\d+(?:\.\d+)?)\s*(?:x)?", RegexOptions.IgnoreCase);
    private static readonly Regex Threshold = new(@"(?:threshold|roll|need|requires?)\D{0,20}(\d{1,4})\s*(?:or higher|\+)?", RegexOptions.IgnoreCase);
    public static string NormalizeDigits(string text) { if (text is null) return ""; return new string(text.Select(c => c is >= '\ue060' and <= '\ue069' ? (char)('0' + c - '\ue060') : c).ToArray()); }
    public static bool ContainsStop(string text) => text is not null && Stop.IsMatch(text);
    public static bool TryTransition(string text, out decimal from, out decimal to) { from = to = 0; var matches = Transition.Matches(NormalizeDigits(text ?? "")); return matches.Count == 1 && decimal.TryParse(matches[0].Groups[1].Value, System.Globalization.NumberStyles.AllowDecimalPoint, System.Globalization.CultureInfo.InvariantCulture, out from) && decimal.TryParse(matches[0].Groups[2].Value, System.Globalization.NumberStyles.AllowDecimalPoint, System.Globalization.CultureInfo.InvariantCulture, out to) && to > from && from >= 1; }
    public static bool TryThreshold(string text, out int threshold) { threshold = 0; var matches = Threshold.Matches(NormalizeDigits(text ?? "")); return matches.Count == 1 && int.TryParse(matches[0].Groups[1].Value, out threshold) && threshold is >= 1 and <= 999; }
}

public static class MacroCompiler {
    public static IReadOnlyList<string> Validate(string script) {
        var errors = new List<string>(); if (string.IsNullOrWhiteSpace(script)) return errors;
        foreach (var line in script.Split('\n', StringSplitOptions.RemoveEmptyEntries)) { var s = line.Trim(); if (s.StartsWith("/wait", StringComparison.OrdinalIgnoreCase) && !Regex.IsMatch(s, "^/wait\\s+\"?\\d+\"?$", RegexOptions.IgnoreCase) && !Regex.IsMatch(s, @"<wait\.\d+>", RegexOptions.IgnoreCase)) errors.Add("Invalid wait: " + s); else if (s.StartsWith('/') && !Regex.IsMatch(s, @"^/(p|party|dice|em|emote|wait)\b", RegexOptions.IgnoreCase)) errors.Add("Unsupported command: " + s); }
        return errors;
    }
}
internal static class Defaults {
    public static PluginSettings Create() {
        var s = new PluginSettings {
            RulesScript = "/p APPLE CRASH: Enroll and set your bet with the host before the round.\n/p Say STOP in party chat to cash out at the last successful multiplier.\n/p A roll equal to the threshold passes. A failed roll freezes STOP for host review.\n/p Payout includes your original stake; remaining stakes are lost only after host review.",
            IntroScript = "/p APPLE CRASH! Stakes committed. Starting at 1x. Say STOP to cash out.\n/apple motion",
            WinTemplate = "{name}@{world} cashed out at {multiplier}x for {payout} gil!",
            LossTemplate = "{name}@{world} lost their {stake} gil stake.",
            ReferencePresets = [new() {From=1.3m,To=1.5m,Threshold=175,DelaySeconds=10,Script="/p Inactive reference: 1.3 to 1.5, roll 175 OR HIGHER."}],
            Steps = [new() { From = 1, To = 1.1m, Threshold = 190 }, new() { From = 1.1m, To = 1.2m, Threshold = 170 }, new() { From = 1.2m, To = 1.3m, Threshold = 150 }, new() { From = 1.3m, To = 1.4m }, new() { From = 1.4m, To = 1.5m }, new() { From = 1.5m, To = 2, Threshold = 265 }, new() { From = 2, To = 2.5m, Threshold = 220 }, new() { From = 2.5m, To = 3, Threshold = 185 }, new() { From = 3, To = 4, Threshold = 270 }, new() { From = 4, To = 5, Threshold = 220 }, new() { From = 5, To = 7, Threshold = 300 }, new() { From = 7, To = 10, Threshold = 315 }, new() { From = 10, To = 20, Threshold = 540 }]
        };
        foreach(var step in s.Steps){step.DelaySeconds=step.From==1?1:10;step.Script="/p {from} to {to}! Roll {threshold} OR HIGHER to pass. STOP now to cash out!\n/wait {delay}\n/dice party";}
        return s;
    }
}

public sealed class GameEngine {
    private readonly string directory, file, backup; private static readonly JsonSerializerOptions Json = new(JsonSerializerDefaults.Web) { WriteIndented = true, Converters = { new JsonStringEnumConverter() } };
    private LedgerState state = new(); private PluginSettings settings = Defaults.Create();
    public LedgerState State => Clone(state); public PluginSettings Settings => Clone(settings); public string? StorageError { get; private set; }
    private static T Clone<T>(T value) => JsonSerializer.Deserialize<T>(JsonSerializer.Serialize(value, Json), Json)!;
    public GameEngine(string directory, string hostId) {
        if (string.IsNullOrWhiteSpace(hostId)) throw new InvalidOperationException("Host identity is required.");
        var key = Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(hostId)));
        this.directory = Path.Combine(directory, key); file = Path.Combine(this.directory, "ledger.json"); backup = file + ".bak";
        state = new() { HostId = hostId };
        try { Directory.CreateDirectory(this.directory); state = Load(hostId); var settingsFile = Path.Combine(this.directory, "settings.json"); if (File.Exists(settingsFile)) { settings = JsonSerializer.Deserialize<PluginSettings>(File.ReadAllText(settingsFile), Json) ?? throw new InvalidDataException("Empty settings."); ValidateSettings(settings, false); } if (StorageError is null && IsLive(state.Round)) Pause("Recovered on startup; reconcile before resuming."); }
        catch (Exception ex) { StorageError = ex.Message; }
    }
    private LedgerState Load(string host) { try { if (!File.Exists(file)) { if (File.Exists(backup) || File.Exists(file + ".tmp")) throw new InvalidDataException("Missing primary ledger; explicit backup recovery is required."); return new() { HostId = host }; } var s = JsonSerializer.Deserialize<LedgerState>(File.ReadAllText(file), Json) ?? throw new InvalidDataException("Empty ledger."); ValidateLedger(s, host); return s; } catch (Exception ex) { StorageError = ex.Message; return new() { HostId = host }; } }
    private void EnsureWritable() { if (StorageError is not null) throw new InvalidOperationException("Storage is unavailable: " + StorageError); }
    private static void AtomicSave(string target, object value, string? backupPath = null) {
        var tmp = target + ".tmp";
        using (var stream = new FileStream(tmp, FileMode.Create, FileAccess.Write, FileShare.None, 4096, FileOptions.WriteThrough)) { JsonSerializer.Serialize(stream, value, Json); stream.Flush(true); }
        if (File.Exists(target)) File.Replace(tmp, target, backupPath); else File.Move(tmp, target);
    }
    private void Commit(LedgerState next) { EnsureWritable(); ValidateLedger(next, state.HostId); try { AtomicSave(file, next, backup); state = next; } catch (Exception ex) { StorageError = ex.Message; throw new InvalidOperationException("Could not persist transaction; no action acknowledged. Restore a verified backup or reopen storage.", ex); } }
    private LedgerState Copy() { EnsureWritable(); return Clone(state); }
    private static bool IsLive(RoundState? r) => r is not null && r.Phase is not RoundPhase.Idle and not RoundPhase.Completed;
    private static void RequireReason(string? reason) { if (string.IsNullOrWhiteSpace(reason)) throw new InvalidOperationException("A reason is required."); }
    private static void ValidateLedger(LedgerState s, string host) {
        if (s.SchemaVersion != 1 || s.HostId != host || s.Players is null || s.Audit is null || s.History is null) throw new InvalidOperationException("Invalid schema or host identity.");
        if (s.Players.Any(p => p is null || string.IsNullOrWhiteSpace(p.Id) || string.IsNullOrWhiteSpace(p.Name) || string.IsNullOrWhiteSpace(p.World) || p.Balance < 0 || p.PreferredBet < 0) || s.Players.Select(p => p.Id).Distinct().Count() != s.Players.Count || s.Players.Select(p => (p.Name.Trim().ToUpperInvariant(), p.World.Trim().ToUpperInvariant())).Distinct().Count() != s.Players.Count) throw new InvalidOperationException("Invalid player balances or duplicate identities.");
        if (s.Audit.Any(a => a is null || a.TransactionId == Guid.Empty || string.IsNullOrWhiteSpace(a.Kind)) || s.Audit.Select(a => a.TransactionId).Distinct().Count() != s.Audit.Count) throw new InvalidOperationException("Invalid audit history.");
        foreach (var r in s.History.Concat(s.Round is null ? [] : new[] { s.Round })) {
            if (r.Id == Guid.Empty || !Enum.IsDefined(r.Phase) || r.Multiplier < 1 || r.Participants is null || r.Snapshot is null) throw new InvalidOperationException("Invalid round.");
            if (r.Participants.Select(p => p.PlayerId).Distinct().Count() != r.Participants.Count) throw new InvalidOperationException("Duplicate round participant.");
            if (r.Participants.Any(p => !s.Players.Any(a => a.Id == p.PlayerId) || p.Stake <= 0 || p.Payout < 0 || !Enum.IsDefined(p.Status) || p.Status == ParticipantStatus.InPlay && (p.Payout != 0 || p.ExitMultiplier is not null))) throw new InvalidOperationException("Invalid round settlement.");
            if (r.Phase == RoundPhase.Completed && r.Participants.Any(p => p.Status == ParticipantStatus.InPlay)) throw new InvalidOperationException("Completed round contains unsettled stakes.");
            if (r.Phase == RoundPhase.AwaitingRoll && r.PendingStep is null || r.Phase != RoundPhase.AwaitingRoll && r.PendingStep is not null) throw new InvalidOperationException("Invalid pending roll.");
        }
    }
    private static List<string> ValidateSettings(PluginSettings s, bool complete) {
        var errors = new List<string>(); if (s.Steps is null || s.Steps.Count == 0) { errors.Add("At least one ladder step is required."); return errors; }
        decimal expected = 1;
        foreach (var step in s.Steps) { if (step is null) { errors.Add("Null step."); continue; } if (step.From != expected || step.To <= step.From || step.To > 20) errors.Add("Ladder must be contiguous from 1x through 20x."); expected = step.To; if (step.Threshold is null) { if (complete) errors.Add($"Unconfigured threshold {step.From} to {step.To}."); } else if (step.Threshold is < 1 or > 999) errors.Add("Threshold must be 1 to 999."); if (step.DelaySeconds is < 0 or > 60) errors.Add("Delay must be 0 to 60 seconds."); errors.AddRange(MacroCompiler.Validate(step.Script)); }
        if (expected != 20) errors.Add("Final step must reach 20x.");
        if (s.RulesScript is null || s.IntroScript is null || s.WinTemplate is null || s.LossTemplate is null) errors.Add("Scripts cannot be null."); else { errors.AddRange(MacroCompiler.Validate(s.RulesScript)); errors.AddRange(MacroCompiler.Validate(s.IntroScript)); }
        if (!complete && errors.Count > 0) throw new InvalidOperationException(string.Join(" ", errors)); return errors;
    }
    private PlayerAccount Player(string id) => State.Players.FirstOrDefault(x => x.Id == id) ?? throw new InvalidOperationException("Unknown player.");
    private void Audit(LedgerState s, string kind, string id, string reason, long amount = 0) => s.Audit.Add(new() { Kind = kind, PlayerId = id, Reason = reason, Amount = amount, RoundId = s.Round?.Id });
    public PlayerAccount AddPlayer(string name, string world) { if (string.IsNullOrWhiteSpace(name) || string.IsNullOrWhiteSpace(world)) throw new InvalidOperationException("Name and world are required."); var s = Copy(); if (s.Players.Any(x => x.Name.Equals(name, StringComparison.OrdinalIgnoreCase) && x.World.Equals(world, StringComparison.OrdinalIgnoreCase))) throw new InvalidOperationException("Player already exists."); var p = new PlayerAccount { Id = Guid.NewGuid().ToString("N"), Name = name.Trim(), World = world.Trim() }; s.Players.Add(p); Audit(s, "PlayerAdded", p.Id, "player added"); Commit(s); return p; }
    public void ConfigurePlayer(string id, long preferredBet, bool enrolled) { if (preferredBet < 0) throw new InvalidOperationException("Bet cannot be negative."); var s = Copy(); var p = s.Players.FirstOrDefault(x => x.Id == id) ?? throw new InvalidOperationException("Unknown player."); p.PreferredBet = preferredBet; p.Enrolled = enrolled; Audit(s, "PlayerConfigured", id, "configuration changed"); Commit(s); }
    public void AdjustBalance(string id, long delta, string reason) { var p = Player(id); checked { SetBalance(id, checked(p.Balance + delta), reason); } }
    public void SetBalance(string id, long balance, string reason) { RequireReason(reason); if (balance < 0) throw new InvalidOperationException("Balance cannot be negative."); var s = Copy(); var p = s.Players.FirstOrDefault(x => x.Id == id) ?? throw new InvalidOperationException("Unknown player."); var before=p.Balance; p.Balance = balance; Audit(s, "BalanceAdjustment", id, reason, balance-before); s.Audit[^1].Before=before;s.Audit[^1].After=balance; Commit(s); }
    public IReadOnlyList<string> ValidateStart() { var e = ValidateSettings(settings, true); if (StorageError is not null) e.Add("Storage unavailable: " + StorageError); if (IsLive(state.Round)) e.Add("A round is already active."); var players = state.Players.Where(x => x.Enrolled && !x.Archived).ToList(); if (players.Count == 0) e.Add("Enroll at least one player."); foreach (var p in players) { if (p.PreferredBet <= 0) e.Add($"{p.Name}: preferred bet must be positive."); else if (p.Balance < p.PreferredBet) e.Add($"{p.Name}: insufficient balance."); else try { var liability = checked((long)decimal.Floor(p.PreferredBet * 20m)); _ = checked(p.Balance - p.PreferredBet + liability); } catch (OverflowException) { e.Add($"{p.Name}: maximum payout overflows."); } } return e; }
    public void StartRound() { var errors = ValidateStart(); if (errors.Count > 0) throw new InvalidOperationException(string.Join(" ", errors)); var s = Copy(); if (s.Round is not null) s.History.Add(s.Round); var r = new RoundState { Id = Guid.NewGuid(), Phase = RoundPhase.Running, Snapshot = Clone(settings) }; s.Round = r; foreach (var p in s.Players.Where(x => x.Enrolled && !x.Archived)) { p.Balance -= p.PreferredBet; r.Participants.Add(new() { PlayerId = p.Id, Name = p.Name, World = p.World, Stake = p.PreferredBet }); Audit(s,"Stake",p.Id,"round stake",-p.PreferredBet); } Audit(s, "RoundStarted", "", "stakes committed"); Commit(s); }
    public void ArmNextStep() { if (state.Round is not { Phase: RoundPhase.Running } r) throw new InvalidOperationException("Round is not running."); var step = r.Snapshot.Steps.FirstOrDefault(x => x.From == r.Multiplier) ?? throw new InvalidOperationException("No next step configured."); if (step.Threshold is null) throw new InvalidOperationException("Step threshold is unconfigured."); var s = Copy(); s.Round!.PendingStep = Clone(step); s.Round.Phase = RoundPhase.AwaitingRoll; Audit(s,"StepArmed","","awaiting roll"); Commit(s); }
    public void AcceptRoll(int roll) { if (State.Round is not { Phase: RoundPhase.AwaitingRoll, PendingStep: not null } r) throw new InvalidOperationException("No roll is pending."); var s = Copy(); var step = s.Round!.PendingStep!; if (roll < step.Threshold) { s.Round.Phase = RoundPhase.CrashReview; s.Round.PendingStep = null; Audit(s, "Crash", "", $"roll {roll} below {step.Threshold}"); Commit(s); return; } s.Round.Multiplier = step.To; s.Round.PendingStep = null; s.Round.Phase = s.Round.Multiplier >= 20m ? RoundPhase.Completed : RoundPhase.Running; if (s.Round.Phase == RoundPhase.Completed) foreach (var p in s.Round.Participants.Where(x => x.Status == ParticipantStatus.InPlay)) Settle(s, p, s.Round.Multiplier, ParticipantStatus.CashedOut); Audit(s, "RollAccepted", "", $"roll {roll}"); Commit(s); }
    private static void Settle(LedgerState s, RoundParticipant rp, decimal multiplier, ParticipantStatus status) { rp.Status = status; rp.ExitMultiplier = multiplier; rp.Payout = checked((long)decimal.Floor(rp.Stake * multiplier)); var p = s.Players.First(x => x.Id == rp.PlayerId); p.Balance = checked(p.Balance + rp.Payout); s.Audit.Add(new() {Kind="Payout",PlayerId=rp.PlayerId,Amount=rp.Payout,RoundId=s.Round!.Id,Reason="settlement",Before=p.Balance-rp.Payout,After=p.Balance}); }
    public void CashOut(string id, bool manual = false, string? reason = null) { if (manual) RequireReason(reason); var existing = state.Round?.Participants.FirstOrDefault(x => x.PlayerId == id) ?? throw new InvalidOperationException("Not in round."); if (existing.Status != ParticipantStatus.InPlay) return; if (state.Round!.Phase is not RoundPhase.Running and not RoundPhase.AwaitingRoll && !(manual && state.Round.Phase is RoundPhase.CrashReview or RoundPhase.RecoveryPaused)) throw new InvalidOperationException("Cash-out is unavailable."); var s = Copy(); var p = s.Round!.Participants.First(x => x.PlayerId == id); Settle(s, p, s.Round.Multiplier, ParticipantStatus.CashedOut); Audit(s, manual ? "ManualCashOut" : "CashOut", id, reason ?? "STOP"); if (s.Round.Participants.All(x=>x.Status!=ParticipantStatus.InPlay)) {s.Round.Phase=RoundPhase.Completed;s.Round.PendingStep=null;} Commit(s); }
    public void FinishCrash(string reason) { RequireReason(reason); if(state.Round?.Phase==RoundPhase.Completed)return; if (state.Round is not { Phase: RoundPhase.CrashReview }) throw new InvalidOperationException("Crash review is not active."); var s = Copy(); foreach (var p in s.Round!.Participants.Where(x => x.Status == ParticipantStatus.InPlay)) { p.Status = ParticipantStatus.Lost; Audit(s, "Loss", p.PlayerId, reason,p.Stake); } s.Round.Phase = RoundPhase.Completed; Commit(s); }
    public void Pause(string reason) { RequireReason(reason); if (!IsLive(state.Round)) throw new InvalidOperationException("No active round."); if(state.Round!.Phase==RoundPhase.RecoveryPaused)return; var s = Copy(); s.Round!.ResumePhase=s.Round.Phase==RoundPhase.CrashReview?RoundPhase.CrashReview:RoundPhase.Running; s.Round.Phase = RoundPhase.RecoveryPaused; s.Round.PendingStep = null; Audit(s, "Paused", "", reason); Commit(s); }
    public void Resume(string reason) { RequireReason(reason); if (State.Round is not { Phase: RoundPhase.RecoveryPaused }) throw new InvalidOperationException("Round is not paused."); var s = Copy(); s.Round!.Phase = s.Round.ResumePhase==RoundPhase.CrashReview?RoundPhase.CrashReview:RoundPhase.Running; s.Round.ResumePhase=null; Audit(s, "Resumed", "", reason); Commit(s); }
    public void RefundActive(string reason) { RequireReason(reason); if (state.Round is null) throw new InvalidOperationException("No round."); if(state.Round.Phase==RoundPhase.Completed)return; var s = Copy(); foreach (var rp in s.Round!.Participants.Where(x => x.Status == ParticipantStatus.InPlay)) { var p = s.Players.First(x => x.Id == rp.PlayerId); p.Balance = checked(p.Balance + rp.Stake); rp.Status = ParticipantStatus.Refunded; rp.Payout=rp.Stake; Audit(s, "Refund", rp.PlayerId, reason, rp.Stake); s.Audit[^1].Before=p.Balance-rp.Stake;s.Audit[^1].After=p.Balance; } s.Round.Phase = RoundPhase.Completed; s.Round.PendingStep=null; Commit(s); }
    public void CorrectMultiplier(decimal multiplier, string reason) { RequireReason(reason); if (!IsLive(state.Round)) throw new InvalidOperationException("No active round."); if (multiplier < 1 || multiplier>20) throw new InvalidOperationException("Multiplier must be 1 to 20."); if (multiplier!=1 && !state.Round!.Snapshot.Steps.Any(x=>x.To==multiplier)) throw new InvalidOperationException("Multiplier must match a snapshot ladder boundary."); var s = Copy(); var before=s.Round!.Multiplier;s.Round.Multiplier = multiplier; s.Round.PendingStep=null; if(s.Round.Phase==RoundPhase.AwaitingRoll)s.Round.Phase=RoundPhase.RecoveryPaused; Audit(s, "MultiplierCorrection", "", $"{reason}; {before} -> {multiplier}"); Commit(s); }
    public void CorrectPayout(string id, long payout, string reason) { RequireReason(reason); if (payout < 0) throw new InvalidOperationException("Payout cannot be negative."); var s = Copy(); var r = s.Round ?? throw new InvalidOperationException("No round."); var rp = r.Participants.FirstOrDefault(x => x.PlayerId == id) ?? throw new InvalidOperationException("Not in round."); if(rp.Status==ParticipantStatus.InPlay)throw new InvalidOperationException("Settle the participant before correcting a payout."); var p = s.Players.First(x => x.Id == id); var delta = checked(payout - rp.Payout); long balance;try{balance=checked(p.Balance+delta);}catch(OverflowException ex){throw new InvalidOperationException("Correction overflows balance.",ex);}if (balance < 0) throw new InvalidOperationException("Correction would make balance negative."); if(delta==0)return;var before=p.Balance;p.Balance = balance; rp.Payout = payout; Audit(s, "PayoutCorrection", id, reason, delta);s.Audit[^1].Before=before;s.Audit[^1].After=balance; Commit(s); }
    public void SaveSettings(PluginSettings settings) { EnsureWritable(); if (IsLive(state.Round)) throw new InvalidOperationException("Settings cannot change during a round."); ValidateSettings(settings,false); try { AtomicSave(Path.Combine(directory,"settings.json"),settings,Path.Combine(directory,"settings.json.bak")); this.settings=Clone(settings); } catch(Exception ex) {StorageError=ex.Message;throw new InvalidOperationException("Could not save settings.",ex);} }
    public void Export(string path) { EnsureWritable(); if(File.Exists(path))throw new InvalidOperationException("Export target already exists."); try{using var stream=new FileStream(path,FileMode.CreateNew,FileAccess.Write,FileShare.None);JsonSerializer.Serialize(stream,state,Json);stream.Flush(true);}catch(Exception ex){throw new InvalidOperationException("Export failed.",ex);} }
    public void Import(string path) { EnsureWritable(); if (IsLive(state.Round)) throw new InvalidOperationException("Cannot import during a round."); try {var imported = JsonSerializer.Deserialize<LedgerState>(File.ReadAllText(path), Json) ?? throw new InvalidDataException(); ValidateLedger(imported,state.HostId); if(IsLive(imported.Round))throw new InvalidOperationException("Cannot import a live round."); foreach(var old in state.Audit)if(!imported.Audit.Any(a=>a.TransactionId==old.TransactionId&&JsonSerializer.Serialize(a,Json)==JsonSerializer.Serialize(old,Json)))throw new InvalidOperationException("Import would discard or modify local audit history. Use an empty isolated directory for a different ledger."); Audit(imported,"Import","","explicit validated import"); Commit(imported);}catch(Exception ex)when(ex is not InvalidOperationException){throw new InvalidOperationException("Import failed validation.",ex);} }
    public void RestoreBackup() { try{if (!File.Exists(backup)) throw new InvalidOperationException("No backup exists."); var restored = JsonSerializer.Deserialize<LedgerState>(File.ReadAllText(backup), Json) ?? throw new InvalidDataException(); ValidateLedger(restored,state.HostId);if(IsLive(restored.Round)){restored.Round!.ResumePhase=restored.Round.Phase==RoundPhase.CrashReview?RoundPhase.CrashReview:RoundPhase.Running;restored.Round.Phase=RoundPhase.RecoveryPaused;restored.Round.PendingStep=null;}Audit(restored,"BackupRestored","","explicit recovery from last-known-good backup");AtomicSave(file,restored);state=restored;StorageError=null;}catch(Exception ex){StorageError=ex.Message;throw new InvalidOperationException("Backup recovery failed.",ex);} }
    public void ArchivePlayer(string id) { var s = Copy(); var p = s.Players.FirstOrDefault(x => x.Id == id) ?? throw new InvalidOperationException("Unknown player."); if (p.Balance != 0 || s.Round?.Participants.Any(x => x.PlayerId == id && x.Status == ParticipantStatus.InPlay) == true) throw new InvalidOperationException("Player has unsettled funds."); p.Archived = true; p.Enrolled = false; Audit(s, "PlayerArchived", id, "archived"); Commit(s); }
}
